<?php

/**
 * Every file under lib/ belongs to exactly one functional component (ADR-012 Rule 1).
 *
 * The functional components of ADR-012 are defined by file pattern in
 * sigrid.components.yaml, generated by scripts/component-patterns.py from the
 * `component` column of scripts/component-map.csv. This test reads both the way
 * Sigrid and gate 122 do (a full regex match on the path with a leading slash,
 * an exclude wins over an include) and fails when a file under lib/ falls in no
 * component (Sigrid's Remainder) or in more than one, when a file has no csv row,
 * when the yaml puts a file in another component than the csv, and when the yaml
 * is not the generator's output. lib/Migration is left out, as Sigrid excludes it.
 *
 * A stale csv row (its file moved away) is not a failure: the generator reports it,
 * so the lanes that move files do not collide on the csv.
 *
 * SPDX-License-Identifier: EUPL-1.2
 * SPDX-FileCopyrightText: 2026 Conduction B.V.
 *
 * @category Test
 * @package  OCA\OpenRegister\Tests\Unit\Architecture
 *
 * @author    Conduction Development Team <info@conduction.nl>
 * @copyright 2026 Conduction B.V.
 * @license   EUPL-1.2 https://joinup.ec.europa.eu/collection/eupl/eupl-text-eupl-12
 *
 * @link https://www.OpenRegister.nl
 */

declare(strict_types=1);

namespace OCA\OpenRegister\Tests\Unit\Architecture;

use PHPUnit\Framework\TestCase;
use RecursiveDirectoryIterator;
use RecursiveIteratorIterator;
use Symfony\Component\Yaml\Yaml;

class ComponentDefinitionTest extends TestCase {

	/**
	 * The repository root.
	 *
	 * @var string
	 */
	private const ROOT = __DIR__ . '/../../..';

	/**
	 * The generated components block.
	 *
	 * @var string
	 */
	private const YAML = self::ROOT . '/sigrid.components.yaml';

	/**
	 * The component map.
	 *
	 * @var string
	 */
	private const CSV = self::ROOT . '/scripts/component-map.csv';

	/**
	 * Paths Sigrid excludes from every component.
	 *
	 * @var array<int, string>
	 */
	private const EXCLUDED = ['lib/Migration/'];

	/**
	 * Every PHP file under lib/, as `lib/...`, sorted; lib/Migration excepted.
	 *
	 * @return array<int, string>
	 */
	private function libFiles(): array {
		$root  = realpath(self::ROOT);
		$files = [];
		$walk  = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root.'/lib', RecursiveDirectoryIterator::SKIP_DOTS));
		foreach ($walk as $file) {
			if ($file->isFile() === false || $file->getExtension() !== 'php') {
				continue;
			}

			$path = substr($file->getPathname(), strlen($root) + 1);
			foreach (self::EXCLUDED as $excluded) {
				if (str_starts_with($path, $excluded) === true) {
					continue 2;
				}
			}

			$files[] = $path;
		}

		sort($files);
		return $files;
	}//end libFiles()

	/**
	 * The components of the yaml: name => [include patterns, exclude patterns].
	 *
	 * @return array<string, array{include: array<int, string>, exclude: array<int, string>}>
	 */
	private function components(): array {
		$data = Yaml::parseFile(self::YAML);
		$this->assertIsArray($data);
		$this->assertIsArray($data['components'] ?? null, 'sigrid.components.yaml has no components: block');

		$components = [];
		foreach ($data['components'] as $component) {
			$components[(string) $component['name']] = [
				'include' => array_map('strval', $component['include'] ?? []),
				'exclude' => array_map('strval', $component['exclude'] ?? []),
			];
		}

		return $components;
	}//end components()

	/**
	 * The csv rows: [file rows, directory rows], each `lib/...` path => component.
	 *
	 * @return array{0: array<string, string>, 1: array<string, string>}
	 */
	private function rows(): array {
		$handle = fopen(self::CSV, 'r');
		$this->assertNotFalse($handle);
		$header = fgetcsv($handle, null, ',', '"', '');
		$this->assertIsArray($header);
		$this->assertContains('component', $header, 'scripts/component-map.csv has no component column');

		$files = [];
		$dirs  = [];
		while (($line = fgetcsv($handle, null, ',', '"', '')) !== false) {
			if ($line === [null]) {
				continue;
			}

			$row  = array_combine($header, $line);
			$path = 'lib/'.trim((string) $row['file']);
			if (str_ends_with($path, '/') === true) {
				$dirs[rtrim($path, '/')] = trim((string) $row['component']);
				continue;
			}

			$files[$path] = trim((string) $row['component']);
		}

		fclose($handle);
		return [$files, $dirs];
	}//end rows()

	/**
	 * Whether a Sigrid pattern matches the whole path.
	 *
	 * @param string $pattern The pattern, a regular expression without delimiters.
	 * @param string $path    The path, with a leading slash.
	 *
	 * @return boolean
	 */
	private function fullMatch(string $pattern, string $path): bool {
		return preg_match('#\A(?:'.str_replace('#', '\#', $pattern).')\z#', $path) === 1;
	}//end fullMatch()

	/**
	 * The components a path falls in, exclude winning over include.
	 *
	 * @param array<string, array{include: array<int, string>, exclude: array<int, string>}> $components The yaml components.
	 * @param string                                                                         $path       The `lib/...` path.
	 *
	 * @return array<int, string>
	 */
	private function matching(array $components, string $path): array {
		$matched = [];
		foreach ($components as $name => $patterns) {
			foreach ($patterns['exclude'] as $pattern) {
				if ($this->fullMatch($pattern, '/'.$path) === true) {
					continue 2;
				}
			}

			foreach ($patterns['include'] as $pattern) {
				if ($this->fullMatch($pattern, '/'.$path) === true) {
					$matched[] = $name;
					continue 2;
				}
			}
		}

		return $matched;
	}//end matching()

	/**
	 * The component the csv gives a path: its file row, else the deepest directory row.
	 *
	 * @param string                $path  The `lib/...` path.
	 * @param array<string, string> $files File rows.
	 * @param array<string, string> $dirs  Directory rows.
	 *
	 * @return string|null Null when no row covers the path.
	 */
	private function csvComponent(string $path, array $files, array $dirs): ?string {
		if (isset($files[$path]) === true) {
			return $files[$path];
		}

		$directory = dirname($path);
		while ($directory !== 'lib' && $directory !== '.') {
			if (isset($dirs[$directory]) === true) {
				return $dirs[$directory];
			}

			$directory = dirname($directory);
		}

		return null;
	}//end csvComponent()

	/**
	 * The csv row to add for a file, with a placeholder for its component.
	 *
	 * @param string $path The `lib/...` path.
	 *
	 * @return string
	 */
	private function rowFor(string $path): string {
		$file = substr($path, 4);
		return $file.',,'.explode('/', $file)[0].',,,,,<component>';
	}//end rowFor()

	/**
	 * Every file under lib/ matches exactly one component: none falls in a Remainder.
	 *
	 * @return void
	 */
	public function testEveryFileMatchesExactlyOneComponent(): void {
		$components = $this->components();
		$problems   = [];
		foreach ($this->libFiles() as $path) {
			$matched = $this->matching($components, $path);
			if (count($matched) === 0) {
				$problems[] = $path.' matches no component (Remainder): add the row `'.$this->rowFor(path: $path).'` to scripts/component-map.csv and run python3 scripts/component-patterns.py';
			} else if (count($matched) > 1) {
				$problems[] = $path.' matches '.implode(' and ', $matched).': fix its row in scripts/component-map.csv and run python3 scripts/component-patterns.py';
			}
		}

		$this->assertSame([], $problems, implode("\n", $problems));
	}//end testEveryFileMatchesExactlyOneComponent()

	/**
	 * Every file outside the directory rows has a csv row, and the yaml agrees with it.
	 *
	 * @return void
	 */
	public function testEveryFileHasACsvRowAndTheYamlAgrees(): void {
		[$files, $dirs] = $this->rows();
		$components     = $this->components();
		$problems       = [];
		foreach ($this->libFiles() as $path) {
			$expected = $this->csvComponent($path, $files, $dirs);
			if ($expected === null) {
				$problems[] = $path.' has no row: add the row `'.$this->rowFor(path: $path).'` to scripts/component-map.csv';
				continue;
			}

			if (isset($components[$expected]) === false) {
				$problems[] = $path.' has component '.$expected.' in scripts/component-map.csv, which sigrid.components.yaml does not define';
				continue;
			}

			$matched = $this->matching($components, $path);
			if ($matched !== [$expected]) {
				$problems[] = $path.' is '.$expected.' in scripts/component-map.csv but matches ['.implode(', ', $matched).'] in sigrid.components.yaml: run python3 scripts/component-patterns.py';
			}
		}

		$this->assertSame([], $problems, implode("\n", $problems));
	}//end testEveryFileHasACsvRowAndTheYamlAgrees()

	/**
	 * The yaml is exactly the generator's output.
	 *
	 * @return void
	 */
	public function testYamlIsTheGeneratorsOutput(): void {
		$python = trim((string) shell_exec('command -v python3 2>/dev/null'));
		if ($python === '') {
			$this->markTestSkipped('python3 is not installed; the yaml was still checked against the csv file by file.');
		}

		$output = [];
		$status = 0;
		exec(escapeshellarg($python).' '.escapeshellarg(self::ROOT.'/scripts/component-patterns.py').' --check 2>&1', $output, $status);
		$this->assertSame(0, $status, implode("\n", $output));
	}//end testYamlIsTheGeneratorsOutput()
}//end class
